contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address _to, uint256 _value) public payable {
        require(_to != address(0));
        require(address(this) != _to);

        c.transfer(address(this), 0);

        uint256 fromBefore = c.balanceOf(address(this));
        uint256 toBefore = c.balanceOf(_to);

        bool reverted;
        bool success;
        try c.transfer(_to, _value) returns (bool s) {
            success = s;
            reverted = false;
        } catch {
            success = false;
            reverted = true;
        }

        uint256 fromAfter = c.balanceOf(address(this));
        uint256 toAfter = c.balanceOf(_to);

        if (!reverted) {
            assert(success);
            assert(fromAfter == fromBefore - _value);
            assert(toAfter == toBefore + _value);
        } else {
            assert(fromAfter == fromBefore);
            assert(toAfter == toBefore);
        }
    }
}

